python3 -I -c '
import random,math
random.seed(0)
n=100000; K=28
res={1.96:0,1.645:0}
for _ in range(n):
    s=0.0; hit={1.96:False,1.645:False}
    for k in range(1,K+1):
        s+=random.gauss(0,1); z=s/math.sqrt(k)
        for c in hit:
            if z>c: hit[c]=True
    for c in hit: res[c]+=hit[c]
for c,v in res.items():
    p=v/n; print(c, "1 metric:",round(p,3)," 8 independent:",round(1-(1-p)**8,3))
'
